/*
 * baseui design tokens.
 * Color names are baseui's; spacing, radius, shadow, focus, motion follow Astryx structure.
 * Order mirrors "All Tokens": Color, Spacing, Size, Radius, Shadow, Focus, Duration, Easing, Z-index, Typography.
 * Theme: [data-theme="light" | "dark"] on <html>.
 */

@font-face{font-family:Geist;src:url("./fonts/geist-cyrillic-D_Kiv5N3.woff2") format("woff2");font-weight:100 900;font-style:normal;font-display:swap;unicode-range:U+301,U+400-45F,U+490-491,U+4B0-4B1,U+2116}
@font-face{font-family:Geist;src:url("./fonts/geist-latin-ext-Dr5IBr7O.woff2") format("woff2");font-weight:100 900;font-style:normal;font-display:swap;unicode-range:U+100-2BA,U+2BD-2C5,U+2C7-2CC,U+2CE-2D7,U+2DD-2FF,U+304,U+308,U+329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF}
@font-face{font-family:Geist;src:url("./fonts/geist-latin-BGnTDqni.woff2") format("woff2");font-weight:100 900;font-style:normal;font-display:swap;unicode-range:U+??,U+131,U+152-153,U+2BB-2BC,U+2C6,U+2DA,U+2DC,U+304,U+308,U+329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}

/* ---------- Color ---------- */
:root,
[data-theme="light"] {
  color-scheme: light;

  /* Text and Icon */
  --baseui-text-and-icon-primary: #171717;
  --baseui-text-and-icon-secondary: #5f6877;
  --baseui-text-and-icon-disabled: #babfca;
  --baseui-text-and-icon-accent: #575df6;

  /* Background */
  --baseui-background-primary: #ffffff;
  --baseui-background-secondary: #eff2f6;
  --baseui-background-tertiary: #d4dae2;
  --baseui-background-disabled: #f0f0f0;
  --baseui-background-accent: #575df6;
  --baseui-background-brand: #171717;

  /* Border */
  --baseui-border-primary: #e0e2e6;
  --baseui-border-accent: #ccd4e1;
  --baseui-border-disabled: #dfe0e2;

  /* Accent Colors */
  --baseui-accent-colors-green-light: #bbfb60;
  --baseui-accent-colors-pink: #ef9ffa;
  --baseui-accent-colors-blue: #575df6;
  --baseui-accent-colors-green: #53b67d;
  --baseui-accent-colors-orange: #f5ba44;
  --baseui-accent-colors-blue-light: #8abafa;
  --baseui-accent-colors-red: #e8634c;

  /* Extensions / Text and Icon */
  --baseui-extensions-text-and-icon-error: #e8634c;
  --baseui-extensions-text-and-icon-warning: #f5ba44;
  --baseui-extensions-text-and-icon-success: #44cf5e;
  --baseui-extensions-text-and-icon-always-dark: #171717;
  --baseui-extensions-text-and-icon-always-light: #ffffff;
  --baseui-extensions-text-and-icon-on-color: #ffffff;
  --baseui-extensions-text-and-icon-on-brand: #ffffff;

  /* Extensions / Background */
  --baseui-extensions-background-surface: #ffffff;
  --baseui-extensions-background-inverse-primary: #171717;
  --baseui-extensions-background-overlay-dark: rgba(0, 0, 0, 0.5);
  --baseui-extensions-background-overlay-light: rgba(255, 255, 255, 0.7);
  --baseui-extensions-background-always-dark: #171717;
  --baseui-extensions-background-always-light: #ffffff;
  --baseui-extensions-background-error: #e8634c;
  --baseui-extensions-background-warning: #f5ba44;
  --baseui-extensions-background-success: #44cf5e;
  --baseui-extensions-background-light-success: #dff7e3;
  --baseui-extensions-background-light-accent: #e7e8fe;
  --baseui-extensions-background-light-error: #f9d8d2;
  --baseui-extensions-background-light-warning: #fbe2b2;

  /* Extensions / Border */
  --baseui-extensions-border-selected: #171717;
  --baseui-extensions-border-selected-always-dark: #171717;
  --baseui-extensions-border-selected-always-light: #ffffff;
  --baseui-extensions-border-accent: #575df6;
  --baseui-extensions-border-error: #e8634c;
  --baseui-extensions-border-warning: #f5ba44;
  --baseui-extensions-border-success: #44cf5e;

  /* Hover */
  --baseui-background-primary-hover: #f5f7fa;
  --baseui-background-secondary-hover: #e5e9ef;
  --baseui-background-tertiary-hover: #c8cfd9;
  --baseui-background-accent-hover: #4b51ec;
  --baseui-background-brand-hover: #3b3b3b;
  --baseui-background-transparent-hover: rgba(88, 122, 172, 0.06);
  --baseui-extensions-background-surface-hover: #f5f7fa;
  --baseui-extensions-background-error-hover: #d9523b;
  --baseui-extensions-background-warning-hover: #e7a92c;
  --baseui-extensions-background-success-hover: #37bd51;
  --baseui-extensions-background-light-accent-hover: #dcdefd;
  --baseui-text-and-icon-primary-hover: #2c2c2c;
  --baseui-text-and-icon-secondary-hover: #464f5d;
  --baseui-extensions-text-and-icon-on-color-hover: #e1e1e1;
  --baseui-extensions-text-and-icon-on-brand-hover: #e1e1e1;
  --baseui-text-and-icon-disabled-hover: #9ea3ad;
  --baseui-text-and-icon-accent-hover: #423ed6;
  --baseui-background-disabled-hover: #e3e3e3;
  --baseui-border-primary-hover: #c9cbcf;
  --baseui-border-accent-hover: #b6bdca;
  --baseui-border-disabled-hover: #c8c9cb;
  --baseui-accent-colors-green-light-hover: #aeed51;
  --baseui-accent-colors-pink-hover: #db8ce6;
  --baseui-accent-colors-blue-hover: #4949e1;
  --baseui-accent-colors-green-hover: #3ea36b;
  --baseui-accent-colors-orange-hover: #e1a72a;
  --baseui-accent-colors-blue-light-hover: #78a7e6;
  --baseui-accent-colors-red-hover: #d3503a;
  --baseui-extensions-text-and-icon-error-hover: #c84630;
  --baseui-extensions-text-and-icon-warning-hover: #d79d19;
  --baseui-extensions-text-and-icon-success-hover: #15b241;
  --baseui-extensions-text-and-icon-always-dark-hover: #2c2c2c;
  --baseui-extensions-text-and-icon-always-light-hover: #e1e1e1;
  --baseui-extensions-background-inverse-primary-hover: #252525;
  --baseui-extensions-background-overlay-dark-hover: rgba(0, 0, 0, 0.6);
  --baseui-extensions-background-overlay-light-hover: rgba(255, 255, 255, 0.8);
  --baseui-extensions-background-always-dark-hover: #252525;
  --baseui-extensions-background-always-light-hover: #f2f2f2;
  --baseui-extensions-background-light-success-hover: #d2ead6;
  --baseui-extensions-background-light-error-hover: #eccbc5;
  --baseui-extensions-background-light-warning-hover: #eed5a5;
  --baseui-extensions-border-selected-hover: #272727;
  --baseui-extensions-border-selected-always-dark-hover: #272727;
  --baseui-extensions-border-selected-always-light-hover: #e8e8e8;
  --baseui-extensions-border-accent-hover: #4645dd;
  --baseui-extensions-border-error-hover: #cf4c37;
  --baseui-extensions-border-warning-hover: #dea425;
  --baseui-extensions-border-success-hover: #23b847;

}

[data-theme="dark"] {
  color-scheme: dark;

  /* Text and Icon */
  --baseui-text-and-icon-primary: #ffffff;
  --baseui-text-and-icon-secondary: #999999;
  --baseui-text-and-icon-disabled: #7a7a7a;
  --baseui-text-and-icon-accent: #575df6;

  /* Background */
  --baseui-background-primary: #121212;
  --baseui-background-secondary: #252525;
  --baseui-background-tertiary: #2c2c2c;
  --baseui-background-disabled: #373737;
  --baseui-background-accent: #575df6;
  --baseui-background-brand: #ffffff;

  /* Border */
  --baseui-border-primary: #2d2d2d;
  --baseui-border-accent: #484848;
  --baseui-border-disabled: #333333;

  /* Accent Colors */
  --baseui-accent-colors-green-light: #bbfb60;
  --baseui-accent-colors-pink: #ef9ffa;
  --baseui-accent-colors-blue: #575df6;
  --baseui-accent-colors-green: #53b67d;
  --baseui-accent-colors-orange: #f5ba44;
  --baseui-accent-colors-blue-light: #8abafa;
  --baseui-accent-colors-red: #e8634c;

  /* Extensions / Text and Icon */
  --baseui-extensions-text-and-icon-error: #e8634c;
  --baseui-extensions-text-and-icon-warning: #f5ba44;
  --baseui-extensions-text-and-icon-success: #44cf5e;
  --baseui-extensions-text-and-icon-always-dark: #171717;
  --baseui-extensions-text-and-icon-always-light: #ffffff;
  --baseui-extensions-text-and-icon-on-color: #171717;
  --baseui-extensions-text-and-icon-on-brand: #171717;

  /* Extensions / Background */
  --baseui-extensions-background-surface: #1b1b1b;
  --baseui-extensions-background-inverse-primary: #ffffff;
  --baseui-extensions-background-overlay-dark: rgba(0, 0, 0, 0.7);
  --baseui-extensions-background-overlay-light: rgba(18, 18, 18, 0.7);
  --baseui-extensions-background-always-dark: #171717;
  --baseui-extensions-background-always-light: #ffffff;
  --baseui-extensions-background-error: #e8634c;
  --baseui-extensions-background-warning: #f5ba44;
  --baseui-extensions-background-success: #44cf5e;
  --baseui-extensions-background-light-success: #114119;
  --baseui-extensions-background-light-accent: #24276a;
  --baseui-extensions-background-light-error: #51150a;
  --baseui-extensions-background-light-warning: #503806;

  /* Extensions / Border */
  --baseui-extensions-border-selected: #ffffff;
  --baseui-extensions-border-selected-always-dark: #171717;
  --baseui-extensions-border-selected-always-light: #ffffff;
  --baseui-extensions-border-accent: #575df6;
  --baseui-extensions-border-error: #e8634c;
  --baseui-extensions-border-warning: #f5ba44;
  --baseui-extensions-border-success: #44cf5e;

  /* Hover */
  --baseui-background-primary-hover: #1c1c1c;
  --baseui-background-secondary-hover: #2e2e2e;
  --baseui-background-tertiary-hover: #363636;
  --baseui-background-accent-hover: #6a6ff8;
  --baseui-background-brand-hover: #e0e0e0;
  --baseui-background-transparent-hover: rgba(255, 255, 255, 0.05);
  --baseui-extensions-background-surface-hover: #222222;
  --baseui-extensions-background-error-hover: #ee7561;
  --baseui-extensions-background-warning-hover: #f8c866;
  --baseui-extensions-background-success-hover: #5bda73;
  --baseui-extensions-background-light-accent-hover: #2d3180;
  --baseui-text-and-icon-primary-hover: #e1e1e1;
  --baseui-text-and-icon-secondary-hover: #b5b5b5;
  --baseui-extensions-text-and-icon-on-color-hover: #2c2c2c;
  --baseui-extensions-text-and-icon-on-brand-hover: #2c2c2c;
  --baseui-text-and-icon-disabled-hover: #959595;
  --baseui-text-and-icon-accent-hover: #7383fc;
  --baseui-background-disabled-hover: #444444;
  --baseui-border-primary-hover: #3b3b3b;
  --baseui-border-accent-hover: #555555;
  --baseui-border-disabled-hover: #404040;
  --baseui-accent-colors-green-light-hover: #aeed51;
  --baseui-accent-colors-pink-hover: #db8ce6;
  --baseui-accent-colors-blue-hover: #4949e1;
  --baseui-accent-colors-green-hover: #3ea36b;
  --baseui-accent-colors-orange-hover: #e1a72a;
  --baseui-accent-colors-blue-light-hover: #78a7e6;
  --baseui-accent-colors-red-hover: #d3503a;
  --baseui-extensions-text-and-icon-error-hover: #fe8871;
  --baseui-extensions-text-and-icon-warning-hover: #d79d19;
  --baseui-extensions-text-and-icon-success-hover: #15b241;
  --baseui-extensions-text-and-icon-always-dark-hover: #2c2c2c;
  --baseui-extensions-text-and-icon-always-light-hover: #e1e1e1;
  --baseui-extensions-background-inverse-primary-hover: #f2f2f2;
  --baseui-extensions-background-overlay-dark-hover: rgba(0, 0, 0, 0.8);
  --baseui-extensions-background-overlay-light-hover: rgba(18, 18, 18, 0.8);
  --baseui-extensions-background-always-dark-hover: #252525;
  --baseui-extensions-background-always-light-hover: #f2f2f2;
  --baseui-extensions-background-light-success-hover: #235129;
  --baseui-extensions-background-light-error-hover: #63261a;
  --baseui-extensions-background-light-warning-hover: #634508;
  --baseui-extensions-border-selected-hover: #e8e8e8;
  --baseui-extensions-border-selected-always-dark-hover: #272727;
  --baseui-extensions-border-selected-always-light-hover: #e8e8e8;
  --baseui-extensions-border-accent-hover: #6c7aff;
  --baseui-extensions-border-error-hover: #fd7d65;
  --baseui-extensions-border-warning-hover: #dea425;
  --baseui-extensions-border-success-hover: #23b847;

}

/* ---------- Semantic aliases ----------
 * Surface / on-surface pairs, so a component names its role, not a palette entry:
 * background: var(--baseui-popover); color: var(--baseui-on-popover).
 * They only point at the colors above, so they follow the theme (also a nested [data-theme]). */
:root,
[data-theme] {
  --baseui-surface: var(--baseui-background-primary);
  --baseui-on-surface: var(--baseui-text-and-icon-primary);
  --baseui-on-surface-muted: var(--baseui-text-and-icon-secondary);
  --baseui-muted: var(--baseui-background-secondary);
  --baseui-on-muted: var(--baseui-text-and-icon-primary);
  --baseui-popover: var(--baseui-extensions-background-surface);
  --baseui-on-popover: var(--baseui-text-and-icon-primary);
  --baseui-accent: var(--baseui-background-accent);
  --baseui-on-accent: var(--baseui-extensions-text-and-icon-on-color);
  --baseui-brand: var(--baseui-background-brand);
  --baseui-on-brand: var(--baseui-extensions-text-and-icon-on-brand);
  --baseui-destructive: var(--baseui-extensions-background-error);
  --baseui-on-destructive: var(--baseui-extensions-text-and-icon-on-color);
  --baseui-border: var(--baseui-border-primary);
  --baseui-disabled: var(--baseui-background-disabled);
  --baseui-on-disabled: var(--baseui-text-and-icon-disabled);
}

/* ---------- Spacing ---------- */
:root {
  /* A step is 1 gap = 4px: spacing-1 is 1 gap, spacing-0-5 is half a gap, spacing-4 is 4 gaps. */
  --baseui-spacing-0: 0px;
  --baseui-spacing-0-5: 2px;
  --baseui-spacing-1: 4px;
  --baseui-spacing-1-5: 6px;
  --baseui-spacing-2: 8px;
  --baseui-spacing-3: 12px;
  --baseui-spacing-4: 16px;
  --baseui-spacing-5: 20px;
  --baseui-spacing-6: 24px;
  --baseui-spacing-8: 32px;
  --baseui-spacing-10: 40px;
  --baseui-spacing-12: 48px;
  --baseui-spacing-16: 64px;
  --baseui-spacing-20: 80px;
  /* Negative: multiply any spacing token by this one, e.g. margin-inline: calc(var(--baseui-spacing-4) * var(--baseui-spacing-negative)) */
  --baseui-spacing-negative: -1;
}

/* ---------- Layout ---------- */
/* Page and container geometry. The breakpoints are Tailwind's; media queries cannot read variables, so they are written out in CSS: below md (767px) is mobile, below md (767px) a dialog or a list is a sheet. */
:root {
  /* Margins */
  --baseui-layout-margin-mobile: 20px;
  --baseui-layout-margin-desktop: 24px;

  /* Sizes */
  --baseui-layout-header-height: 64px;
  --baseui-layout-sidebar-width: 280px;
  --baseui-layout-settings-width: 280px;
  --baseui-layout-content-max-width: 1040px;
  --baseui-layout-dialog-width: 520px;
  --baseui-layout-mobile-preview-width: 360px;

  /* Breakpoints (Tailwind's) */
  --baseui-breakpoint-sm: 640px;
  --baseui-breakpoint-md: 768px;
  --baseui-breakpoint-lg: 1024px;
  --baseui-breakpoint-xl: 1280px;
  --baseui-breakpoint-2xl: 1536px;

}

/* ---------- Radius ---------- */
:root {
  /* Scale */
  --baseui-radius-none: 0;
  --baseui-radius-sm: 4px;
  --baseui-radius-md: 6px;
  --baseui-radius-lg: 8px;
  --baseui-radius-xl: 12px;
  --baseui-radius-2xl: 16px;
  --baseui-radius-3xl: 24px;
  --baseui-radius-4xl: 32px;
  --baseui-radius-full: 9999px;

  /* Custom */
  --baseui-radius-custom-10: 10px;
  --baseui-radius-custom-14: 14px;
  --baseui-radius-custom-20: 20px;
  --baseui-radius-custom-28: 28px;

  /* Scale factor */
  --baseui-radius-scale: 1;
}
@supports (width: round(1px, 1px)) {
  :root {
    --baseui-radius-sm: round(calc(4px * var(--baseui-radius-scale)), 0.5px);
    --baseui-radius-md: round(calc(6px * var(--baseui-radius-scale)), 0.5px);
    --baseui-radius-lg: round(calc(8px * var(--baseui-radius-scale)), 0.5px);
    --baseui-radius-xl: round(calc(12px * var(--baseui-radius-scale)), 0.5px);
    --baseui-radius-2xl: round(calc(16px * var(--baseui-radius-scale)), 0.5px);
    --baseui-radius-3xl: round(calc(24px * var(--baseui-radius-scale)), 0.5px);
    --baseui-radius-4xl: round(calc(32px * var(--baseui-radius-scale)), 0.5px);
    --baseui-radius-custom-10: round(calc(10px * var(--baseui-radius-scale)), 0.5px);
    --baseui-radius-custom-14: round(calc(14px * var(--baseui-radius-scale)), 0.5px);
    --baseui-radius-custom-20: round(calc(20px * var(--baseui-radius-scale)), 0.5px);
    --baseui-radius-custom-28: round(calc(28px * var(--baseui-radius-scale)), 0.5px);
  }
}

/* ---------- Shadow ---------- */
:root {
  --baseui-shadow-color: rgb(from var(--baseui-extensions-background-always-dark) r g b / 12%);
  --baseui-shadow-sm: 0 2px 8px 0 var(--baseui-shadow-color);
  --baseui-shadow-md: 0 6px 20px 0 var(--baseui-shadow-color);
  --baseui-shadow-lg: 0 4px 28px 0 var(--baseui-shadow-color);
}

/* ---------- Focus ---------- */
:root {
  --baseui-focus-outline-width: 2px;
  --baseui-focus-outline-style: solid;
  --baseui-focus-outline-color: var(--baseui-text-and-icon-primary);
  --baseui-focus-outline-offset: 2px;
}

/* ---------- Duration & easing (instant under prefers-reduced-motion) ---------- */
:root {
  --baseui-duration-150: 150ms;
  --baseui-duration-300: 300ms;
  --baseui-duration-500: 500ms;
  /* Tailwind's easings */
  --baseui-ease-in: cubic-bezier(0.4, 0, 1, 1);
  --baseui-ease-out: cubic-bezier(0, 0, 0.2, 1);
  --baseui-ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
}
/* data-motion="off" on <html> does the same for the whole page; "basic" drops the extra effects of "enhanced" (the default) */
[data-motion="off"] {
  --baseui-duration-150: 0ms;
  --baseui-duration-300: 0ms;
  --baseui-duration-500: 0ms;
}
@media (prefers-reduced-motion: reduce) {
  :root {
    --baseui-duration-150: 0ms;
    --baseui-duration-300: 0ms;
    --baseui-duration-500: 0ms;
  }
}

/* ---------- Z-index ---------- */
:root {
  --baseui-z-index-10: 10;
  --baseui-z-index-20: 20;
  --baseui-z-index-30: 30;
  --baseui-z-index-40: 40;
  --baseui-z-index-50: 50;
}

/* Typography */
:root {
  /* Tailwind's text sizes and weights (text-sm, font-semibold ...); the composite styles below are built from these numbers */
  --baseui-text-xs: 12px;
  --baseui-text-xs--line-height: 16px;
  --baseui-text-sm: 14px;
  --baseui-text-sm--line-height: 20px;
  --baseui-text-base: 16px;
  --baseui-text-base--line-height: 24px;
  --baseui-text-xl: 20px;
  --baseui-text-xl--line-height: 28px;
  --baseui-text-2xl: 24px;
  --baseui-text-2xl--line-height: 32px;
  --baseui-font-weight-normal: 400;
  --baseui-font-weight-medium: 500;
  --baseui-font-weight-semibold: 600;
  --baseui-font-weight-bold: 700;

  --baseui-typography-font-family:var(--font-geist,"Geist"), system-ui, -apple-system, "Segoe UI", sans-serif;
  --baseui-typography-font-family-mono:ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --baseui-typography-header-56:700 56px / 60px var(--baseui-typography-headline-font-family, var(--baseui-typography-font-family));
  --baseui-typography-header-48:700 48px / 52px var(--baseui-typography-headline-font-family, var(--baseui-typography-font-family));
  --baseui-typography-header-40:700 40px / 44px var(--baseui-typography-headline-font-family, var(--baseui-typography-font-family));
  --baseui-typography-header-32:700 32px / 36px var(--baseui-typography-headline-font-family, var(--baseui-typography-font-family));
  --baseui-typography-header-28:700 28px / 32px var(--baseui-typography-headline-font-family, var(--baseui-typography-font-family));
  --baseui-typography-header-24:700 24px / 28px var(--baseui-typography-headline-font-family, var(--baseui-typography-font-family));
  --baseui-typography-header-20:700 20px / 24px var(--baseui-typography-headline-font-family, var(--baseui-typography-font-family));
  --baseui-typography-text-20-semi-bold:600 20px / 28px var(--baseui-typography-font-family);
  --baseui-typography-text-20-regular:400 20px / 28px var(--baseui-typography-font-family);
  --baseui-typography-text-16-bold:700 16px / 24px var(--baseui-typography-font-family);
  --baseui-typography-text-16-semi-bold:600 16px / 24px var(--baseui-typography-font-family);
  --baseui-typography-text-16-regular:400 16px / 24px var(--baseui-typography-font-family);
  --baseui-typography-text-14-bold:700 14px / 20px var(--baseui-typography-font-family);
