/* ---------- Base ---------- */
:root {
  -webkit-tap-highlight-color: transparent;
}
:where(a, button, input, select, textarea, label, summary, [role="button"], [role="radio"], [role="option"], [role="tab"], [role="combobox"], [role="switch"], [role="checkbox"]) {
  touch-action: manipulation;
