   flush   on the edge of a field (offset 0), like the Text Input: the OTP cells */
:is(.bui-tab, .bui-tabpanel, .bui-collapsible__trigger, .bui-banner__close, .bui-toast__close, .bui-breadcrumbs__link, .bui-page, .bui-link, .bui-avatar--interactive, .bui-table__sortbtn, .bui-slider input[type="range"]):focus-visible,
:is(.bui-card--clickable, .bui-card--selectable):has(.bui-card__hit:focus-visible) { outline: var(--baseui-focus-outline-width) var(--baseui-focus-outline-style) var(--baseui-focus-outline-color); outline-offset: var(--baseui-focus-outline-offset); }
:is(.bui-segmented__item, .bui-calendar__nav, .bui-calendar__day, .bui-table tbody tr.is-clickable, .bui-bottombar__item):focus-visible { outline: var(--baseui-focus-outline-width) var(--baseui-focus-outline-style) var(--baseui-focus-outline-color); outline-offset: calc(var(--baseui-focus-outline-width) * -1); }
